const fixtures=[{id:'CR-01',shop:'Sample shop A',kg:12,price:60,time:'17:30',state:'available'},{id:'CR-02',shop:'Sample shop B',kg:8,price:55,time:'18:00',state:'available'},{id:'CR-03',shop:'Sample shop C',kg:15,price:65,time:'18:30',state:'available'}];let lots;try{lots=JSON.parse(localStorage.getItem('cactusrelay-demo-v1'));if(!Array.isArray(lots)||lots.length!==3)throw Error()}catch{lots=structuredClone(fixtures)}const root=document.getElementById('lots'),message=document.getElementById('message');function save(){try{localStorage.setItem('cactusrelay-demo-v1',JSON.stringify(lots))}catch{message.textContent='Storage unavailable. This demo works until you reload.'}}function render(){root.innerHTML=lots.map((l,i)=>`<article class="lot"><span class="status">${l.state}</span><h3 style="margin-top:20px">${l.shop}</h3><span class="caption">${l.id} · Fictional tomato lot</span><div class="big-num">${l.kg} kg</div><p>₽${l.price}/kg · Simulated cutoff ${l.time}</p>${l.state==='available'?`<button data-action="reserve" data-i="${i}">Reserve this lot</button>`:''}${l.state==='reserved'?`<label for="weight-${i}">Actual collected weight (kg)</label><input id="weight-${i}" type="number" min="0.1" max="${l.kg}" step="0.1" value="${l.kg}"><button data-action="collect" data-i="${i}">Confirm collection</button>`:''}${['available','reserved'].includes(l.state)?`<button style="background:transparent;color:var(--green);border:1px solid" data-action="expire" data-i="${i}">Simulate expiry</button>`:''}${l.state==='collected'?`<p>Receipt ${l.id}-DEMO<br>${l.actual} kg collected · ₽${(l.actual*l.price).toFixed(2)}<br><small>Demonstration receipt only</small></p>`:''}${l.state==='expired'?'<p>Collection window closed.</p>':''}</article>`).join('')}root.addEventListener('click',e=>{const b=e.target.closest('button[data-action]');if(!b)return;const i=Number(b.dataset.i),l=lots[i],a=b.dataset.action;if(a==='reserve'&&l.state==='available'){l.state='reserved';message.textContent=l.id+' reserved in this browser. Confirm the actual handoff weight.'}else if(a==='collect'&&l.state==='reserved'){const value=Number(document.getElementById('weight-'+i).value);if(!Number.isFinite(value)||value<=0||value>l.kg){message.textContent='Enter a collected weight greater than zero and no more than '+l.kg+' kg.';return}l.state='collected';l.actual=value;message.textContent=l.id+': demo handoff confirmed. '+value+' kg recorded.'}else if(a==='expire'&&['available','reserved'].includes(l.state)){l.state='expired';message.textContent=l.id+' expired in the simulation.'}save();render()});document.getElementById('reset').addEventListener('click',()=>{lots=structuredClone(fixtures);save();render();message.textContent='Sample lots reset. All three are available.'});render();